{
  "tasks": [
    {
      "task_id": "T01",
      "title": "按项目统计任务分布与工时概况",
      "business_question": "各项目的任务数量及总工时是多少？以识别主要工作负载集中在哪些项目。",
      "priority": "P0",
      "priority_reason": "直接响应“探索项目任务数据的主要分布”的核心需求，提供基于关键维度（项目）的聚合视图，是理解数据全貌的基础。",
      "requirement_ids": ["C01"],
      "depends_on": [],
      "missing_inputs": [],
      "steps": [
        {
          "step_id": "S01",
          "operation": "group_aggregate",
          "params": {
            "metrics": [
              {
                "function": "count",
                "field": null,
                "alias": "task_count"
              },
              {
                "function": "sum",
                "field": "field_0004",
                "alias": "total_hours"
              }
            ],
            "dimensions": [
              "field_0002"
            ]
          }
        }
      ]
    },
    {
      "task_id": "T02",
      "title": "按状态分析任务分布与工时差异",
      "business_question": "不同状态下的任务数量及平均工时是多少？以探索任务完成进度与资源投入之间的潜在差异。",
      "priority": "P1",
      "priority_reason": "补充性分析，通过另一个关键维度（状态）揭示数据的另一面，帮助理解“差异”，但不影响对核心分布的基本认知。",
      "requirement_ids": ["C01"],
      "depends_on": [],
      "missing_inputs": [],
      "steps": [
        {
          "step_id": "S01",
          "operation": "group_aggregate",
          "params": {
            "metrics": [
              {
                "function": "count",
                "field": null,
                "alias": "task_count"
              },
              {
                "function": "avg",
                "field": "field_0004",
                "alias": "avg_hours"
              }
            ],
            "dimensions": [
              "field_0003"
            ]
          }
        }
      ]
    },
    {
      "task_id": "T03",
      "title": "任务工时整体分布特征",
      "business_question": "所有任务的工时中位数、最小值、最大值和平均值是多少？以了解工时的集中趋势和离散程度。",
      "priority": "P2",
      "priority_reason": "描述性统计，提供数值型字段（工时）的整体画像，辅助判断数据质量或异常值，属于基础概况信息。",
      "requirement_ids": ["C01"],
      "depends_on": [],
      "missing_inputs": [],
      "steps": [
        {
          "step_id": "S01",
          "operation": "aggregate",
          "params": {
            "metrics": [
              {
                "function": "median",
                "field": "field_0004",
                "alias": "median_hours"
              },
              {
                "function": "min",
                "field": "field_0004",
                "alias": "min_hours"
              },
              {
                "function": "max",
                "field": "field_0004",
                "alias": "max_hours"
              },
              {
                "function": "avg",
                "field": "field_0004",
                "alias": "avg_hours"
              }
            ]
          }
        }
      ]
    }
  ]
